#define IN00 0x0036
#define IN01 0x06c0
#define IN02 0x6900
#define OUT0 0x000f

#define IN10 0x5048
#define IN11 0x2106
#define IN12 0x8411
#define OUT1 0x00f0

#define IN20 0x8601
#define IN21 0x4828
#define IN22 0x10c4
#define OUT2 0x3300

#define IN30 0x2980
#define IN31 0x9011
#define IN32 0x022a
#define OUT3 0xcc00





void mcg_init()
{
    unsigned int i,j;








    static int sbits[8][6] = {
        {2,5,6,9,11,13},
        {1,4,7,10,8,14},
        {3,6,8,13,0,15},
        {12,14,1,2,4,10},
        {0,10,3,14,6,12},
        {7,8,12,15,1,5},
        {9,15,5,11,2,7},
        {11,13,0,4,3,9}
    };
    for (i=0; i<TSIZE; i++) {
        stable[i]=0;
        for (j=0; j<8; j++)
        stable[i] |=
            sboxes[j][((i>>sbits[j][0])&1)
            | (((i>>sbits[j][1])&1)<<1)
            | (((i>>sbits[j][2])&1)<<2)
            | (((i>>sbits[j][3])&1)<<3)
            | (((i>>sbits[j][4])&1)<<4)
            | (((i>>sbits[j][5])&1)<<5)];
    }
}




void mcg_keyset(unsigned char* key,mcg_key* ek)
{
    int i,j;
    unsigned char k[2][8];
    mcg_init();
    strncpy((char*)k[0],(const char*)&key[0],8);
    strncpy((char*)k[1],(const char*)&key[8],8);


    for (i=0; i<KSIZE; i++)
        ek->val[i]=0;
    for (i=0; i<2; i++)
        for (j=0; j<32; j++) {
        mcg_block_encrypt(k[i],ek);
        ek->val[j*3] ^= k[i][0] | (k[i][1]<<8);
        ek->val[j*3+1] ^= k[i][2] | (k[i][3]<<8);
        ek->val[j*3+2] ^= k[i][4] | (k[i][5]<<8);
        }
}




void mcg_block_encrypt(unsigned char* blk,mcg_key* key)
{
    unsigned short r0, r1, r2, r3, a, b, c;
    int i;
    unsigned short *ek;

    r0=blk[0] | (blk[1]<<8);
    r1=blk[2] | (blk[3]<<8);
    r2=blk[4] | (blk[5]<<8);
    r3=blk[6] | (blk[7]<<8);
    ek = &(key->val[0]);

    for (i=0; i<(ROUNDS/4); i++) {
        a = r1 ^ *(ek++); b = r2 ^ *(ek++); c = r3 ^ *(ek++);
        r0 ^= ((OUT0 & stable[(a & IN00) | (b & IN01) | (c & IN02)])
            | (OUT1 & stable[(a & IN10) | (b & IN11) | (c & IN12)])
            | (OUT2 & stable[(a & IN20) | (b & IN21) | (c & IN22)])
            | (OUT3 & stable[(a & IN30) | (b & IN31) | (c & IN32)]));
        a = r2 ^ *(ek++); b = r3 ^ *(ek++); c = r0 ^ *(ek++);
        r1 ^= ((OUT0 & stable[(a & IN00) | (b & IN01) | (c & IN02)])
            | (OUT1 & stable[(a & IN10) | (b & IN11) | (c & IN12)])
            | (OUT2 & stable[(a & IN20) | (b & IN21) | (c & IN22)])
            | (OUT3 & stable[(a & IN30) | (b & IN31) | (c & IN32)]));
        a = r3 ^ *(ek++); b = r0 ^ *(ek++); c = r1 ^ *(ek++);
        r2 ^= ((OUT0 & stable[(a & IN00) | (b & IN01) | (c & IN02)])
            | (OUT1 & stable[(a & IN10) | (b & IN11) | (c & IN12)])
            | (OUT2 & stable[(a & IN20) | (b & IN21) | (c & IN22)])
            | (OUT3 & stable[(a & IN30) | (b & IN31) | (c & IN32)]));
        a = r0 ^ *(ek++); b = r1 ^ *(ek++); c = r2 ^ *(ek++);
        r3 ^= ((OUT0 & stable[(a & IN00) | (b & IN01) | (c & IN02)])
            | (OUT1 & stable[(a & IN10) | (b & IN11) | (c & IN12)])
            | (OUT2 & stable[(a & IN20) | (b & IN21) | (c & IN22)])
            | (OUT3 & stable[(a & IN30) | (b & IN31) | (c & IN32)]));
    }

    blk[0] = r0; blk[1] = r0>>8;
    blk[2] = r1; blk[3] = r1>>8;
    blk[4] = r2; blk[5] = r2>>8;
    blk[6] = r3; blk[7] = r3>>8;
}




void mcg_block_decrypt(unsigned char *blk,mcg_key* key)
{
    unsigned short r0, r1, r2, r3, a, b, c;
    int i;
    unsigned short *ek;


    r0=blk[0] | (blk[1]<<8);
    r1=blk[2] | (blk[3]<<8);
    r2=blk[4] | (blk[5]<<8);
    r3=blk[6] | (blk[7]<<8);
    ek = &(key->val[KSIZE]);

    for (i=0; i<(ROUNDS/4); ++i) {
        c = r2 ^ *(--ek); b = r1 ^ *(--ek); a = r0 ^ *(--ek);
        r3 ^= ((OUT0 & stable[(a & IN00) | (b & IN01) | (c & IN02)])
            | (OUT1 & stable[(a & IN10) | (b & IN11) | (c & IN12)])
            | (OUT2 & stable[(a & IN20) | (b & IN21) | (c & IN22)])
            | (OUT3 & stable[(a & IN30) | (b & IN31) | (c & IN32)]));
        c = r1 ^ *(--ek); b = r0 ^ *(--ek); a = r3 ^ *(--ek);
        r2 ^= ((OUT0 & stable[(a & IN00) | (b & IN01) | (c & IN02)])
            | (OUT1 & stable[(a & IN10) | (b & IN11) | (c & IN12)])
            | (OUT2 & stable[(a & IN20) | (b & IN21) | (c & IN22)])
            | (OUT3 & stable[(a & IN30) | (b & IN31) | (c & IN32)]));
        c = r0 ^ *(--ek); b = r3 ^ *(--ek); a = r2 ^ *(--ek);
        r1 ^= ((OUT0 & stable[(a & IN00) | (b & IN01) | (c & IN02)])
            | (OUT1 & stable[(a & IN10) | (b & IN11) | (c & IN12)])
            | (OUT2 & stable[(a & IN20) | (b & IN21) | (c & IN22)])
            | (OUT3 & stable[(a & IN30) | (b & IN31) | (c & IN32)]));
        c = r3 ^ *(--ek); b = r2 ^ *(--ek); a = r1 ^ *(--ek);
        r0 ^= ((OUT0 & stable[(a & IN00) | (b & IN01) | (c & IN02)])
            | (OUT1 & stable[(a & IN10) | (b & IN11) | (c & IN12)])
            | (OUT2 & stable[(a & IN20) | (b & IN21) | (c & IN22)])
            | (OUT3 & stable[(a & IN30) | (b & IN31) | (c & IN32)]));
    }

    blk[0] = r0; blk[1] = r0>>8;
    blk[2] = r1; blk[3] = r1>>8;
    blk[4] = r2; blk[5] = r2>>8;
    blk[6] = r3; blk[7] = r3>>8;
}
