#ifdef EXTRA_FUNC




void ErrAbort (char *s)
{
	fprintf (stderr, "%s\n", s);
	exit (1);
}









void ConvertChunkOfBytes (char* charBuffer,word32* wordBuffer)
{
	int     i;
	word32 t0, t1, t2, t3;

	for (i = 0; i < CHUNK_SIZE; i++) {
		t0 = charBuffer[4*i];
		t1 = charBuffer[4*i + 1];
		t2 = charBuffer[4*i + 2];
		t3 = charBuffer[4*i + 3];
		t0 &= 0xffL;
		t1 &= 0xffL;
		t2 &= 0xffL;
		t3 &= 0xffL;
		wordBuffer[i] = (t0 << 24) | (t1 << 16) | (t2 << 8) | t3;
	};
}









int ReadChunk (word32* buf)
{
	char    charBuf[CHUNK_SIZE*4];
	int     byteCount;
	int     i;

	byteCount = fread (charBuf, 1, CHUNK_SIZE*4, stdin);
	if (byteCount < 0)
			ErrAbort ("error on read");

	for (i = byteCount; i < CHUNK_SIZE*4; i++)
		charBuf[i] = 0;




	ConvertChunkOfBytes (charBuf, buf);
	return (byteCount);
}
#endif











void HashN (word32* output, word32* input)
{
	static int shiftTable[4] = {16, 8, 16, 24};

	word32 block[INPUT_BLOCK_SIZE];
	word32 SBoxEntry;
	int     shift;
	int     i;
	int     index;
	int     next, last;
	int     byteInWord;


	for (i = 0; i < INPUT_BLOCK_SIZE; i++)
		block[i] = input[i];

	for (index = 0; index < SECURITY_LEVEL; index++) {
		for (byteInWord = 0; byteInWord < 4; byteInWord++) {
			for (i = 0; i < INPUT_BLOCK_SIZE; i++) {

				next = (i + 1) & MASK;
				last = (i + MASK) & MASK;

				SBoxEntry = standardSBoxes
					[2*index + ((i / 2) & 1)]
					[block[i] & 0xffL];




				block[next] ^= SBoxEntry;
				block[last] ^= SBoxEntry;
			};




			shift = shiftTable[byteInWord];
			for (i = 0; i < INPUT_BLOCK_SIZE; i++)
				block[i] = (block[i] >> shift) |
					(block[i] << (32 - shift));

		};
	};


	for (i = 0; i < OUTPUT_BLOCK_SIZE; i++)
		output[i] = input[i] ^ block[MASK - i];
};












void Hash512 (word32* output,word32* input)
{
	static int shiftTable[4] = {16, 8, 16, 24};

	word32	block[INPUT_BLOCK_SIZE];
	word32	SBE;
	int     shift, leftShift;
	int     i;
	int     index;
	int     next, last;
	int     byteInWord;
	word32	*SBox0;
	word32	*SBox1;
	word32	B00,B01,B02,B03,B04,B05,B06,B07,B08,B09,B10,B11,B12,B13,B14,B15;


	B00 = input[0];
	B01 = input[1];
	B02 = input[2];
	B03 = input[3];
	B04 = input[4];
	B05 = input[5];
	B06 = input[6];
	B07 = input[7];
	B08 = input[8];
	B09 = input[9];
	B10 = input[10];
	B11 = input[11];
	B12 = input[12];
	B13 = input[13];
	B14 = input[14];
	B15 = input[15];


	for (index = 0; index < SECURITY_LEVEL; index++) {
		SBox0 = standardSBoxes[2*index+0];
		SBox1 = standardSBoxes[2*index+1];
		for (byteInWord = 0; byteInWord < 4; byteInWord++) {
			round_snefru(B15,B00,B01,SBox0);
			round_snefru(B00,B01,B02,SBox0);
			round_snefru(B01,B02,B03,SBox1);
			round_snefru(B02,B03,B04,SBox1);
			round_snefru(B03,B04,B05,SBox0);
			round_snefru(B04,B05,B06,SBox0);
			round_snefru(B05,B06,B07,SBox1);
			round_snefru(B06,B07,B08,SBox1);
			round_snefru(B07,B08,B09,SBox0);
			round_snefru(B08,B09,B10,SBox0);
			round_snefru(B09,B10,B11,SBox1);
			round_snefru(B10,B11,B12,SBox1);
			round_snefru(B11,B12,B13,SBox0);
			round_snefru(B12,B13,B14,SBox0);
			round_snefru(B13,B14,B15,SBox1);
			round_snefru(B14,B15,B00,SBox1);




			shift = shiftTable[byteInWord];
			leftShift = 32-shift;
			rotate(B00);
			rotate(B01);
			rotate(B02);
			rotate(B03);
			rotate(B04);
			rotate(B05);
			rotate(B06);
			rotate(B07);
			rotate(B08);
			rotate(B09);
			rotate(B10);
			rotate(B11);
			rotate(B12);
			rotate(B13);
			rotate(B14);
			rotate(B15);
		};
	};

	output[0] = input[0] ^ B15;
	output[1] = input[1] ^ B14;
	output[2] = input[2] ^ B13;
	output[3] = input[3] ^ B12;
#if OUTPUT_BLOCK_SIZE == 4
    return;
#else
	output[4] = input[4] ^ B11;
	output[5] = input[5] ^ B10;
	output[6] = input[6] ^ B09;
	output[7] = input[7] ^ B08;
#endif


};

#ifdef EXTRA_FUNC



void Increment64BitCounter (word32* counter, long increment)
{
	word32 maxInt = 0xffffffffL;

	if ( (maxInt-counter[1]) < increment) {

		if (counter[0] == maxInt)
			ErrAbort("64-bit counter overflowed");

		counter[0]++;


		counter[1] = maxInt-counter[1];
		counter[1] = increment - counter[1];
	}
	else

	counter[1] += increment;
}





























void main ()
{
	int     i;
	word32 hash[INPUT_BLOCK_SIZE];
	word32 bitCount[2];

	long int byteCount;



	if (SECURITY_LEVEL*2 > MAX_SBOX_COUNT)
		ErrAbort ("Too few S-boxes for specified SECURITY_LEVEL");
	if (OUTPUT_BLOCK_SIZE < 4)
		ErrAbort ("OUTPUT_BLOCK_SIZE too small");
	if ((INPUT_BLOCK_SIZE & MASK) != 0)
		ErrAbort ("logic error, INPUT_BLOCK_SIZE not a power of 2");
	if ((INPUT_BLOCK_SIZE % 4) != 0)
		ErrAbort ("logic error, INPUT_BLOCK_SIZE not a multiple of 4");
	if (OUTPUT_BLOCK_SIZE > INPUT_BLOCK_SIZE - 2)
		ErrAbort ("logic error, OUTPUT_BLOCK_SIZE is too big");
	if (CHUNK_SIZE < 2)
		ErrAbort ("logic error, CHUNK_SIZE is too small");





	bitCount[0] = 0;
	bitCount[1] = 0;
	for (i = 0; i < INPUT_BLOCK_SIZE; i++)
		hash[i] = 0;






	do {

		byteCount = ReadChunk (&hash[OUTPUT_BLOCK_SIZE]);
		Increment64BitCounter (bitCount, 8*byteCount);

		if (byteCount > 0)
			Hash512 (hash, hash);
	} while (byteCount > 0);





	hash[INPUT_BLOCK_SIZE - 2] = bitCount[0];

	hash[INPUT_BLOCK_SIZE - 1] = bitCount[1];


	Hash512 (hash, hash);





	for (i = 0; i < OUTPUT_BLOCK_SIZE; i++)
		printf (" %08lx", hash[i]);


































	printf ("\n");
	exit (0);
}
 #endif
