u4 fi( u4  fi_in, u4  fi_key)
{
	u4  d9, d7;

	d9 = (fi_in >> 7) & 0x1ff;
	d7 = fi_in & 0x7f;
	d9 = s9[d9] ^ d7;
	d7 = (s7[d7] ^ d9) & 0x7f;

	d7 = d7 ^ ((fi_key >> 9) & 0x7f);
	d9 = d9 ^ (fi_key & 0x1ff);
	d9 = s9[d9] ^ d7;
	return ((d7<<9) | d9);
}


u4  fo(u4  *ek, u4  fo_in, byte k)
{
	u4  t0, t1;
	t0 = (fo_in >> 16);
	t1 = fo_in & 0xFFFF;
	t0 ^= ek[k];
	t0 = fi(t0, ek[((k+5)%8) + 8]);
	t0 ^= t1;
	t1 ^= ek[(k+2)%8];
	t1 = fi(t1,ek[((k+1)%8) + 8]);
	t1 ^= t0;
	t0 ^= ek[(k+7)%8];
	t0 = fi(t0, ek[((k+3)%8)+8]);
	t0 ^= t1;
	t1 ^=  ek[(k+4)%8];
	return ( (t1<<16) | t0 );
}


u4  fl(u4  *ek, u4  fl_in, byte k)
{
	u4  d0, d1;
	byte t;

	d0 = (fl_in >> 16);
	d1 = fl_in & 0xffff;
	if ( k % 2 ) {
		t=(k-1)/2;
		d1 = d1 ^ (d0 & ek[((t+2)%8)+8]);
		d0 = d0 ^ (d1 | ek[(t+4)%8]);
	}
	else {
		t=k/2;
		d1 = d1 ^ (d0 & ek[t]);
		d0 = d0 ^ (d1 | ek[((t+6)%8)+8]);
	}
	return ((d0<<16) | d1);
}


u4  flinv(u4  *ek, u4  fl_in, byte k)
{
	u4  d0, d1;
	byte t;

	d0 = (fl_in >> 16);
	d1 = fl_in & 0xffff;

	if ( k % 2 ) {
		t= (k-1)/2;
		d0 = d0 ^ (d1 | ek[(t+4)%8]);
		d1 = d1 ^ (d0 & ek[((t+2)%8)+8]);
	}
	else {
		t = k/2;
		d0 = d0 ^ (d1 | ek[((t+6)%8)+8]);
		d1 = d1 ^ (d0 & ek[t]);
	}
	return ((d0<<16) | d1);
}

void misty1_encrypt_block(u4  *ek, u4  p[2], u4  c[2])
{
	u4  d0, d1;

	d0 = p[0];
	d1 = p[1];


	d0 = fl(ek,d0,0);
	d1=fl(ek,d1,1);
	d1 = d1 ^fo(ek,d0,0);


	d0 = d0^fo(ek,d1,1);


	d0 = fl(ek,d0,2);
	d1=fl(ek,d1,3);
	d1 = d1 ^fo(ek,d0,2);


	d0 = d0^fo(ek,d1,3);


	d0 = fl(ek,d0,4);
	d1=fl(ek,d1,5);
	d1 = d1 ^fo(ek,d0,4);



	d0 = d0^fo(ek,d1,5);


	d0 = fl(ek,d0,6);
	d1=fl(ek,d1,7);
	d1 = d1 ^fo(ek,d0,6);



	d0 = d0^fo(ek,d1,7);


	d0 = fl(ek,d0,8);
	d1=fl(ek,d1,9);


	c[0] = d1;
	c[1]= d0;
}


void misty1_decrypt_block(u4  *ek,u4  c[2], u4  p[2])
{
	u4  d0, d1;

	d0 = c[1];
	d1 = c[0];
	d0 = flinv(ek,d0, 8);
	d1 = flinv(ek,d1, 9);
	d0 = d0 ^ fo(ek,d1, 7);
	d1 = d1 ^ fo(ek,d0, 6);
	d0 = flinv(ek,d0, 6);
	d1 = flinv(ek,d1, 7);
	d0 = d0 ^ fo(ek,d1, 5);
	d1 = d1 ^ fo(ek,d0, 4);
	d0 = flinv(ek,d0, 4);
	d1 = flinv(ek,d1, 5);
	d0 = d0 ^ fo(ek,d1, 3);
	d1 = d1 ^ fo(ek,d0, 2);
	d0 = flinv(ek,d0, 2);
	d1 = flinv(ek,d1, 3);
	d0 = d0 ^ fo(ek,d1, 1);
	d1 = d1 ^ fo(ek,d0, 0);
	d0 = flinv(ek,d0, 0);
	d1 = flinv(ek,d1, 1);
	p[0] = d0;
	p[1] = d1;
}

static void bcopy_u4_byte(u4 k, byte * b) {
	b[3]=(k>>24)&0xFF;
	b[2]=(k>>16)&0xFF;
	b[1]=(k>>8)&0xFF;
	b[0]= k &0xFF;
}

void misty1_keyinit(u4  *ek, u4  *k)
{
	int i;
	byte key[16];

	bcopy_u4_byte(k[0],(byte *)(&key[0]));
	bcopy_u4_byte(k[1],(byte *)(&key[4]));
	bcopy_u4_byte(k[2],(byte *)(&key[8]));
	bcopy_u4_byte(k[3],(byte *)(&key[12]));

	memset(ek,0,MISTY1_KEYSIZE*sizeof(u4));

	for(i=0; i < 8 ; i++) {
		ek[i] = (key[i*2]*256) + (key[(i*2) +1]);
	}

	for (i=0 ; i < 8 ; i++) {
		ek[i+8] = fi(ek[i],ek[(i+1)%8]);
		ek[i+16] = ek[i+8] & 0x1ff;
		ek[i+24] = ek[i+8] >> 9;
	}
}

void misty1_key_destroy(u4  *ek)
{
	memset(ek,0,MISTY1_KEYSIZE*sizeof(u4));
}

